function row=compute_operational_candidate_row_unseen_v1(X,fit,scenario_id,rep,seed,method,r,g,alpha,runtime_seconds)
%COMPUTE_OPERATIONAL_CANDIDATE_ROW_UNSEEN_V1 Truth-free candidate row.
method=string(method);
if isfield(fit,'valid') && fit.valid
    st=compute_external_alpha_fit_stats_v1(X,fit,method);
else
    st=empty_stats();
end
row=table(double(scenario_id),double(rep),double(seed),method,size(X,1),size(X,2),r,g,alpha, ...
 st.W_raw,st.W_ratio,st.R2,st.explained,st.native_score,st.objective_per_keep, ...
 st.trim_rate,st.trim_gap_ratio,st.trim_gap_log10,st.trim_gap_robust, ...
 field_or(fit,'objective',NaN),logical(field_or(fit,'valid',false)), ...
 string(field_or(fit,'message',"")),runtime_seconds,string(field_or(fit,'selector',"")), ...
 field_or(fit,'N_starts',NaN),field_or(fit,'valid_starts',NaN), ...
 string(field_or(fit,'selected_init_family',"")),field_or(fit,'selected_objective_rank',NaN), ...
 field_or(fit,'selector_score',NaN),field_or(fit,'selector_cv_score',NaN), ...
 field_or(fit,'tauW',NaN),field_or(fit,'tauT',NaN), ...
 field_or(fit,'hier_within_family_score',NaN), ...
 field_or(fit,'hier_cross_ari_score',NaN),field_or(fit,'hier_cross_j_score',NaN), ...
 field_or(fit,'hier_cross_H_score',NaN), ...
 'VariableNames',{'scenario_id','replicate','seed','method','n','p','r','g','alpha', ...
 'W_raw','W_ratio','R2','explained','native_score','objective_per_keep','trim_rate', ...
 'trim_gap_ratio','trim_gap_log10','trim_gap_robust','objective','valid','message', ...
 'runtime_seconds','internal_selector','N_starts','valid_starts','selected_init_family', ...
 'selected_objective_rank','selector_score','selector_cv_score','tauW','tauT', ...
 'hier_within_family_score','hier_cross_ari_score','hier_cross_j_score','hier_cross_H_score'});
end
function st=empty_stats()
st=struct('W_raw',NaN,'W_ratio',NaN,'R2',NaN,'explained',NaN,'native_score',NaN, ...
 'objective_per_keep',NaN,'trim_rate',NaN,'trim_gap_ratio',NaN,'trim_gap_log10',NaN,'trim_gap_robust',NaN);
end
function v=field_or(s,name,d)
if isfield(s,name)&&~isempty(s.(name)),v=s.(name);else,v=d;end
end
